#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine.Entities;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [EntityBehaviourDefinition(VanillaContraptionNames.skywardFamiliar)]
    public class SkywardFamiliar : DispenserFamily
    {
        public SkywardFamiliar(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            InitShootTimer(entity);
        }
        protected override void UpdateAI(Entity entity)
        {
            base.UpdateAI(entity);
            entity.SetModelProperty("Multiplier", 1f);
            UpdatePosition(entity);
            ShootTick(entity);
        }
        public override Entity? Shoot(Entity entity)
        {
            var param = entity.GetShootParams();

            var magnitude = STAR_VELOCITY.magnitude;
            var range = entity.GetRange();
            var endRangePoint = entity.GetShootPoint().x + range * entity.GetFacingX();
            Vector3 endPoint = new Vector3(endRangePoint, entity.GetGroundY(), entity.Position.z);
            var angle = (endPoint - entity.GetShootPoint()).normalized;
            param.velocity = angle * magnitude;
            param.pivot = new Vector3(0.5f, 0, 0.5f);

            return entity.ShootProjectile(param);
        }
        public override bool CanEvoke(Entity entity)
        {
            return false;
        }
        protected override int GetTimerTime(Entity entity)
        {
            return FIRE_INTERVAL;
        }
        public void UpdatePosition(Entity entity)
        {
            var parent = entity.Parent;
            if (!parent.ExistsAndAlive())
                return;
            if (!parent.IsEntityOf(VanillaContraptionID.skywardBeacon))
                return;
            entity.SetModelProperty("Dest", parent.GetCenter());
            var targetPosition = GetStrikePosition(entity) + Vector3.up * 80;
            var pos = entity.Position;
            pos.x = pos.x * 0.6f + targetPosition.x * 0.4f;
            pos.y = pos.y * 0.6f + targetPosition.y * 0.4f;
            pos.z = pos.z * 0.6f + targetPosition.z * 0.4f;
            entity.Position = pos;
        }
        public static Vector3 GetStrikePosition(Entity entity)
        {
            var targetColumn = GetTargetColumn(entity);
            var targetLane = GetTargetLane(entity);
            var grid = entity.Level.GetGrid(targetColumn, targetLane);
            if (grid == null)
            {
                var position = entity.Position;
                position.y = entity.GetGroundY();
                return position;
            }
            else
            {
                return entity.Level.GetEntityGridPosition(targetColumn, targetLane);
            }
        }
        public static int GetTargetColumn(Entity entity) => entity.GetBehaviourField<int>(PROP_TARGET_COLUMN);
        public static void SetTargetColumn(Entity entity, int value) => entity.SetBehaviourField(PROP_TARGET_COLUMN, value);
        public static int GetTargetLane(Entity entity) => entity.GetBehaviourField<int>(PROP_TARGET_LANE);
        public static void SetTargetLane(Entity entity, int value) => entity.SetBehaviourField(PROP_TARGET_LANE, value);
        public const int FIRE_INTERVAL = 60;
        public static readonly Vector3 STAR_VELOCITY = new Vector3(20, -20, 0);
        public static readonly VanillaEntityPropertyMeta<int> PROP_TARGET_COLUMN = new VanillaEntityPropertyMeta<int>("target_column", -1);
        public static readonly VanillaEntityPropertyMeta<int> PROP_TARGET_LANE = new VanillaEntityPropertyMeta<int>("target_lane", -1);
    }
}
